using System.Reflection;
using Studio.Core;
using Studio.Raple;
using TKR.Shared.resources;
using TKR.WorldServer.core.objects;
using TKR.WorldServer.core.worlds;

var adapter=new RapleAdapter(Path.GetFullPath(args.FirstOrDefault()??"../raple-realms-7-server"));var checks=0;
void Check(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
void Reject(Action action,string label){try{action();}catch(Exception e)when(e is ArgumentException or InvalidOperationException){Check(true,label);return;}throw new Exception("Expected rejection: "+label);}
const string entity="Cave Pirate Brawler";
BehaviorDocument Doc(string body)=>new("class Fixture{void Build(){db.Init(\""+entity+"\",new State(\"motion\","+body+"));}}",adapter);
World World(EncounterSession session){var engine=typeof(EncounterSession).GetField("engine",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(session)!;return(World)engine.GetType().GetField("World")!.GetValue(engine)!;}
Enemy Boss(EncounterSession session)=>World(session).Enemies.Values.First(e=>e.ObjectDesc.IdName==entity);
object FollowState(EncounterSession session)=>Boss(session).StateStorage.Single(p=>p.Key.GetType().Name=="NewFollow").Value;
bool Following(EncounterSession session)=>(bool)FollowState(session).GetType().GetField("Following")!.GetValue(FollowState(session))!;
foreach(var kind in new[]{"NewFollow","NewCharge","NewWander","NewStayAbove"})Check(adapter.Primitives.Single(p=>p.Name==kind) is{Category:"Movement",Simulatable:true},kind+" exposes its original native movement constructor");
var follow=Doc("new OrderedBehavior(new NewFollow(speed:1,range:1),new NewWander(0))");var wrapper=follow.AllNodes.Single(n=>n.Kind=="OrderedBehavior");var node=follow.AllNodes.Single(n=>n.Kind=="NewFollow");
Check(adapter.OrderedChildren(follow,wrapper)!.All(c=>c.NativeOverride)&&adapter.UsesOrderedDispatch(follow,node),"Ordered source inputs resolve actual native ordered overrides");Check(adapter.EffectiveCallbacks(follow,node).Select(c=>c.Method).SequenceEqual(new[]{"TickCoreOrdered"}),"Effective lifecycle reports ordered ticks without inventing forwarded entry/exit/death callbacks");
using(var native=new EncounterSession(adapter,follow,entity,7,new(Invulnerable:true))){native.Advance(new(),100);Check(Math.Abs(Boss(native).X-65)<.0001&&Boss(native).Y==64.5f,"Original ordered follow moves with BehaviourTickTime and native speed clamping");}
using(var native=new EncounterSession(adapter,Doc("new NewFollow(speed:1,range:1)"),entity,7,new(Invulnerable:true))){native.Advance(new(),200);Check(Boss(native).X==64.5f&&!Boss(native).StateStorage.Any(p=>p.Key.GetType().Name=="NewFollow"),"A direct phase NewFollow does not execute its ordered callback");}
var blocked=Doc("new OrderedBehavior(new Shoot(20,count:4,fixedAngle:0,coolDown:100),new NewFollow(speed:1,range:1))");Check(adapter.OrderedChildren(blocked,blocked.AllNodes.Single(n=>n.Kind=="OrderedBehavior"))![0] is{NativeOverride:false}&&adapter.Validate(blocked,entity).Any(d=>!d.IsError&&d.Message.Contains("no-op")),"Inherited no-op true results are explicitly identified as ordered blockers");using(var native=new EncounterSession(adapter,blocked,entity,7,new(Invulnerable:true))){native.Advance(new(),300);Check(native.Shots.Count==0&&Boss(native).X==64.5f,"A normal Shoot child does nothing and blocks every later ordered movement");}
using(var native=new EncounterSession(adapter,Doc("new OrderedBehavior(new NewFollow(acquireRange:1,speed:1),new NewWander(1))"),entity,7,new(Invulnerable:true))){native.Advance(new(),100);Check(Boss(native).X!=64.5f&&Boss(native).Y!=64.5f,"No-target follow returns false and the next native wander executes");}
using(var native=new EncounterSession(adapter,Doc("new OrderedBehavior(new NewFollow(range:10,speed:1),new NewWander(1))"),entity,7,new(Invulnerable:true))){native.Advance(new(),100);Check(Boss(native).Y!=64.5f&&Following(native),"Follow inside its range returns false while retaining its native following state");}
using(var native=new EncounterSession(adapter,Doc("new OrderedBehavior(new NewWander(0),new NewFollow(speed:1,range:1))"),entity,7,new(Invulnerable:true))){native.Advance(new(),200);Check(Boss(native).X==64.5f&&!Boss(native).StateStorage.Any(p=>p.Key.GetType().Name=="NewFollow"),"Zero-speed wander still returns true and blocks the later follower");}
using(var native=new EncounterSession(adapter,Doc("new OrderedBehavior(new NewStayAbove(.3,5),new NewFollow(speed:1,range:1))"),entity,7,new(Invulnerable:true))){native.Advance(new(),200);Check(Boss(native).X==64.5f,"Native NewStayAbove stops the list without movement outside RealmWorld");}
using(var native=new EncounterSession(adapter,Doc("new OrderedBehavior(new NewFollow(speed:1,range:1))"),entity,7,new(Invulnerable:true))){Boss(native).ApplyConditionEffect(new ConditionEffect(ConditionEffectIndex.Paralyzed,-1));native.Advance(new(),100);Check(Boss(native).X==64.5f,"Original enemy movement dispatch suppresses ordered motion during paralysis");}
using(var native=new EncounterSession(adapter,Doc("new OrderedBehavior(new NewFollow(speed:1,range:1),new NewWander(1))"),entity,7,new(Invulnerable:true),arena:new(){Tiles=[new(65,64,"Arena Dirt",NativeArena.Obstacles().First(o=>o.EnemyOccupySquare&&!o.Connects).Id)]})){native.Advance(new(),100);Check(Boss(native).X==64.5f&&Boss(native).Y==64.5f,"Blocked native MoveToward still returns attempted-displacement true and suppresses fallback");}
using(var native=new EncounterSession(adapter,Doc("new OrderedBehavior(new NewCharge(speed:3,range:10))"),entity,7,new(Invulnerable:true))){native.Advance(new(),100);Check(Math.Abs(Boss(native).X-66)<.0001&&Boss(native).Y==64.5f,"Original ordered charge captures a target and performs its initial step");}
var phaseSource="class Fixture{void Build(){db.Init(\""+entity+"\",new State(new State(\"go\",new OrderedBehavior(new NewFollow(range:10,duration:.2f,cooldown:1)),new TimedTransition(100,\"wait\")),new State(\"wait\",new TimedTransition(100,\"go\"))));}}";
using(var native=new EncounterSession(adapter,new BehaviorDocument(phaseSource,adapter),entity,7,new(Invulnerable:true))){native.Advance(new(),300);Check(Following(native),"Ordered phase exit does not forward the child's native following reset");}
var ids=follow.Identities;follow.MoveNode(node.Id,1,d=>adapter.Validate(d,entity));Check(adapter.OrderedChildren(follow,follow.Find(wrapper.Id))!.Last().Node.Id==node.Id,"Typed child reorder changes actual native dispatch priority");follow.LockedNodes.Add(wrapper.Id);Reject(()=>follow.MoveNode(node.Id,-1,d=>adapter.Validate(d,entity)),"Ordered wrapper locks protect dispatch changes");follow.LockedNodes.Clear();Check(follow.Undo()&&follow.Identities.SequenceEqual(ids),"Ordered source history restores priority and every identity");
var file=adapter.Catalog().Single(e=>e.Id==entity).SourceFile;var supplied=File.ReadAllText(file);
foreach(var body in new[]{"new OrderedBehavior(new NewFollow(speed:1,range:1),new NewWander(.2))","new OrderedBehavior(new NewCharge(speed:3,range:10),new NewWander(0))"})
{var source="using TKR.WorldServer.logic.behaviors.@new;using TKR.WorldServer.logic.behaviors.@new.movements;namespace TKR.WorldServer.logic{public partial class BehaviorDb{private _ StudioOrdered=()=>Behav().Init(\""+entity+"\",new State(\"motion\","+body+"));}}";var project=new StudioProject{SourceFile=file,Source=source,EntityId=entity,Player=new(Invulnerable:true),Seed=7};using var literal=new EncounterSession(adapter,Doc(body),entity,7,project.Player);await using var compiled=await CompiledRuntime.StartAsync(adapter.ServerRoot,project);literal.Advance(new(),600);await compiled.AdvanceAsync(new(),600);Check(literal.Movements.Select(m=>(m.Ms,m.DurationMs,m.ActorId,m.Entity,m.Player,m.FromX,m.FromY,m.ToX,m.ToY,m.Phase)).SequenceEqual(compiled.Movements.Select(m=>(m.Ms,m.DurationMs,m.ActorId,m.Entity,m.Player,m.FromX,m.FromY,m.ToX,m.ToY,m.Phase))),"Literal and compiled "+body.Split('(')[1]+" preserve complete ordered movement samples");}
Check(File.ReadAllText(file)==supplied,"Ordered controller authoring and execution preserve supplied source");Console.WriteLine($"{checks} native ordered-controller checks passed.");
